    /**
     * Method to retrieve the Shift via ShiftFetchOneSummary
     * @param 	summary ShiftFetchOneSummary 
     * @return 	ShiftFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Shift getShift( ShiftFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ShiftFetchOneSummary arg cannot be null" );
    	
    	Shift entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Shift
        	// --------------------------------------
        	CompletableFuture<Shift> futureEntity = queryGateway.query(new FindShiftQuery( new LoadShiftFilter( summary.getShiftId() ) ), ResponseTypes.instanceOf(Shift.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Shift with id " + summary.getShiftId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


